def tope_del_pasillo(capacidades):
    """Devuelve la capacidad MAS GRANDE de la fila, no la mas pequena.

    POR QUE EL MAXIMO: el reparto de mas abajo ya manda el trabajo al cerebro que SI
    aguanta, asi que recortar antes a la medida del mas chico tira material para nada.
    Si la lista viene vacia (o no queda ningun numero util) devuelve 0, que significa
    no recortar nada.
    """
    if not isinstance(capacidades, (list, tuple)):
        return 0
    _utiles = [c for c in capacidades if isinstance(c, (int, float)) and not isinstance(c, bool)]
    if not _utiles:
        return 0
    return max(_utiles)
